//! The VRF account-index golden (`docs/design/test-vectors/golden/vrf-account-index.json`,
//! generated by `crypto/examples/gen_vrf_golden.rs` from the server's own
//! `signet_crypto::vrf`), held against this crate on both compile targets: every case
//! verifies through `vrf_verify` to its index, and every refusal case yields none.
//! Natively, the server's implementation re-proves every case, so the file cannot drift
//! from what the server signs. The committed VRF wasm module is held to the same file
//! in `web/src/lib/crypto/committed_vrf.test.ts`.

#![cfg(feature = "vrf")]

use serde_json::Value;
use signet_crypto_wasm::vrf_verify;

#[cfg(target_arch = "wasm32")]
use wasm_bindgen_test::wasm_bindgen_test;

const GOLDEN: &str = include_str!("../../docs/design/test-vectors/golden/vrf-account-index.json");

fn golden() -> Value {
    serde_json::from_str(GOLDEN).expect("the golden parses")
}

fn h(v: &Value, k: &str) -> Vec<u8> {
    hex::decode(v[k].as_str().expect("a hex field")).expect("hex")
}

#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test)]
#[cfg_attr(not(target_arch = "wasm32"), test)]
fn every_case_verifies_to_its_index_and_every_refusal_to_none() {
    let g = golden();
    let cases = g["cases"].as_array().unwrap();
    let refusals = g["refusals"].as_array().unwrap();
    // The accounting: a case dropped from the file fails here, never passes silently.
    assert_eq!((cases.len(), refusals.len()), (25, 8));
    for c in cases {
        let index = vrf_verify(&h(c, "public_key"), &h(c, "account_id"), &h(c, "proof"))
            .unwrap_or_else(|e| panic!("case {} refused: {e}", c["account_id"]));
        assert_eq!(index, h(c, "index"), "case {}", c["account_id"]);
    }
    for r in refusals {
        assert!(
            vrf_verify(&h(r, "public_key"), &h(r, "account_id"), &h(r, "proof")).is_err(),
            "refusal '{}' verified",
            r["why"]
        );
    }
}

/// The server's implementation re-proves every case: the same public key, proof and index.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn the_server_reproves_every_case() {
    for c in golden()["cases"].as_array().unwrap() {
        let sk: [u8; 32] = h(c, "secret_key").try_into().unwrap();
        let account: [u8; 16] = h(c, "account_id").try_into().unwrap();
        let sk = signet_crypto::vrf::VrfSecretKey::from_bytes(&sk).unwrap();
        let (index, proof) = sk.prove(&account).unwrap();
        assert_eq!(sk.public_key().to_vec(), h(c, "public_key"));
        assert_eq!(proof.to_vec(), h(c, "proof"));
        assert_eq!(index.to_vec(), h(c, "index"));
    }
}
